import{_ as s,a as i}from"./chunks/edit_pack.BgW_0E6q.js";import{_ as n,c as e,o as t,ae as l}from"./chunks/framework.BrQRMotl.js";const E=JSON.parse('{"title":"音色包管理器","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/sound_packs.md","filePath":"zh/manual/sound_packs.md"}'),o={name:"zh/manual/sound_packs.md"};function p(h,a,r,d,c,k){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="音色包管理器" tabindex="-1">音色包管理器 <a class="header-anchor" href="#音色包管理器" aria-label="Permalink to &quot;音色包管理器&quot;">​</a></h1><p>Extended Note Block 的音色包本质上是标准的 <strong>Minecraft 资源包</strong>，这使得它们易于分享和安装。模组提供了一个内置的管理器来简化创建和切换过程。</p><h2 id="打开管理器" tabindex="-1">打开管理器 <a class="header-anchor" href="#打开管理器" aria-label="Permalink to &quot;打开管理器&quot;">​</a></h2><ul><li>在游戏设置页面中，找到并打开 <code>音色包...</code>。</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="_1-浏览与激活" tabindex="-1">1. 浏览与激活 <a class="header-anchor" href="#_1-浏览与激活" aria-label="Permalink to &quot;1. 浏览与激活&quot;">​</a></h3><p><img src="'+s+'" alt="SoundPackManager"></p><ul><li>管理器会列出 <code>resourcepacks</code> 目录下所有识别到的 Extended Note Block 音色包。</li><li>选中一个音色包即可将其激活。这实际上是将该资源包在 Minecraft 的资源包列表中置顶启用。</li></ul><h3 id="_2-创建新音色包" tabindex="-1">2. 创建新音色包 <a class="header-anchor" href="#_2-创建新音色包" aria-label="Permalink to &quot;2. 创建新音色包&quot;">​</a></h3><ul><li>点击“新建”按钮，输入名称，模组会在 <code>.minecraft/resourcepacks/</code> 下自动创建一个新的文件夹结构。</li><li>自动生成的文件包括 <code>pack.mcmeta</code> (资源包元数据) 和 <code>pack.json</code> (音色包配置文件)。</li></ul><h3 id="_3-编辑与刷新" tabindex="-1">3. 编辑与刷新 <a class="header-anchor" href="#_3-编辑与刷新" aria-label="Permalink to &quot;3. 编辑与刷新&quot;">​</a></h3><p><img src="'+i+`" alt="EditPack"></p><ul><li>你可以直接作为普通文件夹打开音色包进行编辑。</li><li>修改文件后，在游戏内点击 <strong>“刷新”</strong>，模组会重新扫描目录，更新 <code>sounds.json</code> 并重载资源，无需重启游戏。</li></ul><h2 id="制作音色包指南" tabindex="-1">制作音色包指南 <a class="header-anchor" href="#制作音色包指南" aria-label="Permalink to &quot;制作音色包指南&quot;">​</a></h2><p>如果你想手动制作或修改音色包，请遵循以下规范：</p><h3 id="目录位置" tabindex="-1">目录位置 <a class="header-anchor" href="#目录位置" aria-label="Permalink to &quot;目录位置&quot;">​</a></h3><p>所有音色包都位于标准资源包目录： <code>.minecraft/resourcepacks/</code></p><h3 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h3><p>一个标准的音色包结构如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MySoundPack/</span></span>
<span class="line"><span>├── pack.mcmeta          # (必须) 标准 Minecraft 资源包元数据</span></span>
<span class="line"><span>├── pack.json            # (必须) Extended Note Block 专用配置</span></span>
<span class="line"><span>└── assets</span></span>
<span class="line"><span>    └── extendednoteblock</span></span>
<span class="line"><span>        ├── sounds.json  # (自动生成) 定义声音事件，通常由模组自动维护</span></span>
<span class="line"><span>        └── sounds</span></span>
<span class="line"><span>            └── notes    # (核心) 放置音频文件的地方</span></span></code></pre></div><h3 id="音频文件规范" tabindex="-1">音频文件规范 <a class="header-anchor" href="#音频文件规范" aria-label="Permalink to &quot;音频文件规范&quot;">​</a></h3><ol><li><strong>格式</strong>: 必须是 <strong><code>.ogg</code></strong> 格式 (Vorbis 编码)。不支持 <code>.wav</code> 或 <code>.mp3</code>。</li><li><strong>命名</strong>: 文件名必须遵循 <code>乐器ID.音符ID.ogg</code> 的格式。 <ul><li><strong>乐器ID</strong>: 对应模组内的乐器编号 (例如 0 是竖琴/钢琴)。</li><li><strong>音符ID</strong>: MIDI 音高编号 (0-127)。</li><li>示例: <code>0.60.ogg</code> 代表乐器 0 (钢琴) 的中央 C 音符。</li></ul></li></ol><h3 id="配置文件-pack-json" tabindex="-1">配置文件 (pack.json) <a class="header-anchor" href="#配置文件-pack-json" aria-label="Permalink to &quot;配置文件 (pack.json)&quot;">​</a></h3><p>这是模组识别音色包的关键文件。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;displayName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的音色包&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available_instruments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">54</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">66</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">72</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 乐器0拥有的采样音高列表</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><em>注意：通常你只需要放入音频文件并点击“刷新”，模组会自动更新这个文件。</em></p><h2 id="为什么使用音色包" tabindex="-1">为什么使用音色包？ <a class="header-anchor" href="#为什么使用音色包" aria-label="Permalink to &quot;为什么使用音色包？&quot;">​</a></h2><ul><li><strong>无限扩展</strong>: 只要按照命名规则放入采样，你可以在游戏里演奏任何真实乐器的声音。</li><li><strong>智能映射</strong>: 你不需要为每个音高都录制采样。模组会自动将未录制的音符映射到最近的可用采样上，并调整音调播放。</li><li><strong>高兼容性</strong>: 既然是标准资源包，你可以像分发普通材质包一样分发你的音色包。</li></ul>`,28)])])}const m=n(o,[["render",p]]);export{E as __pageData,m as default};
